import subprocess

def disassemble(binary_path):
    try:
        # Run ndisasm tool with a specified binary file and 16-bit mode
        result = subprocess.run(["ndisasm", "-b", "16", binary_path], capture_output=True, text=True, timeout=300)
        return result.stdout
    except subprocess.CalledProcessError as e:
        return e.stderr
    except FileNotFoundError:
        return "Error: ndisasm tool not found. Please install it."
    except Exception as ex:
        return str(ex)

if __name__ == "__main__":
    binary_file_path = "/home/ctfplayer/ctf_files/main.bin"
    disassembly_output = disassemble(binary_file_path)
    print(disassembly_output)

